INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `status`, `meta_title`, `meta_description`, `featured_image`, `video`, `content`, `deleted_at`, `created_at`, `updated_at`, `meta_keywords`, `canonical_url`, `og_image`, `is_indexable`, `schema_markup`) VALUES (2, 'دليل الطباعة الرقمية الحديثة', 'دليل-الطباعة-الرقمية', 'تقنيات الطباعة', 'published', 'دليل الطباعة الرقمية الحديثة', 'كل ما تود معرفته عن الطباعة الرقمية والمزايا التنافسية للأعمال.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=1200&q=80', NULL, '<p>محتوى المقال التقني.</p>', NULL, '2026-10-20 15:19:22', '2026-10-20 15:19:22', NULL, NULL, NULL, 1, NULL);
